311	/**
312	 * @brief 从/tmp/wifi.txt文件中提取WiFi SSID
313	 * @param ap_names 用于存储SSID的二维字符数组
314	 * @param max_count ap_names数组的最大行数
315	 * @return 实际提取到的SSID数量
316	 * 
317	 * /tmp/wifi_scan_result.txt文件格式示例:
318	 * bssid / frequency / signal level / encode / ssid
319	 * 74:39:89:f8:f0:ae       5240    -59     0803    Programmers7
320	 * 76:39:89:fe:f0:ae       5240    -62     0803
321	 * 48:8a:d2:d1:62:a2       2412    -73     8000    MERCURY_62A2
322	 * f0:92:b4:a6:03:91       2422    -75     0803    ChinaNet-kRAH
323	 * 74:39:89:f8:f0:ad       2462    -85     0803    Programmers
324	 * 76:39:89:fe:f0:ad       2462    -85     0803
325	 * d2:ad:08:f8:eb:71       2462    -88     0803    DIRECT-71-HP Smart Tank 750
326	 * 7c:c8:4a:e9:39:f8       5180    -92     0803    yankemei168_5G
327	 * 7c:c8:4a:e9:39:fb       5180    -92     0805
328	 * c8:50:e9:bb:f5:0a       2422    -93     0803    ChinaNet-sqJr
329	 */
330	static int get_wifi_ssids(char ap_names[][32], int max_count)
331	{
332	    FILE *fp;
333	    char line[256];
334	    int count = 0;
335	    
336	    // 打开/tmp/wifi_scan_result.txt文件
337	    fp = fopen("/tmp/wifi_scan_result.txt", "r");
338	    if (fp == NULL) {
339	        // 文件不存在或无法打开，返回0
340	        return 0;
341	    }
342	    
343	    // 跳过第一行标题
344	    if (fgets(line, sizeof(line), fp) == NULL) {
345	        fclose(fp);
346	        return 0;
347	    }
348	    
349	    // 逐行读取文件内容
350	    while (fgets(line, sizeof(line), fp) != NULL && count < max_count) {
351	        char *token;
352	        int field_count = 0;
353	        char *saveptr = NULL;
354	        
355	        // 去除行尾的换行符
356	        char *newline = strchr(line, '\n');
357	        if (newline) {
358	            *newline = '\0';
359	        }
360	        
361	        // 使用空格分割字段
362	        token = strtok_r(line, " \t", &saveptr);
363	        while (token != NULL && field_count < 5) {
364	            // 第5个字段是SSID（索引为4）
365	            if (field_count == 4) {
366	                // 复制SSID到ap_names数组中
367	                strncpy(ap_names[count], token, 31);
368	                ap_names[count][31] = '\0'; // 确保字符串结束
369	                count++;
370	                break;
371	            }
372	            token = strtok_r(NULL, " \t", &saveptr);
373	            field_count++;
374	        }
375	    }
376	    
377	    fclose(fp);
378	    return count;
379	}
