106	// 将设备状态转换为本地字符串
107	static const char* ConvertToLocalString(DeviceState state)
108	{
109	    switch (state) {
110	        case kDeviceStateUnknown:
111	            return UNKNOWN_STATUS;
112	        case kDeviceStateStarting:
113	            return INITIALIZING;
114	        case kDeviceStateWifiConfiguring:
115	            return NETWORK_CFG;
116	        case kDeviceStateIdle:
117	            return STANDBY;
118	        case kDeviceStateConnecting:
119	            return CONNECTING;
120	        case kDeviceStateListening:
121	            return LISTENING;
122	        case kDeviceStateSpeaking:
123	            return SPEAKING;
124	        case kDeviceStateUpgrading:
125	            return UPGRADING;
126	        case kDeviceStateActivating:
127	            return ACTIVATION;
128	        case kDeviceStateFatalError:
129	            return ERROR_STR;
130	    }
131	
132	    return "未知状态";
133	}
