135	/*
136	 * 处理从IPC接收到的UI数据。
137	 * 处理的数据格式:
138	 * 1. 状态: {"state": 0}等, 取值对应DeviceState的取值
139	 * 2. 要显示的文本: {"text": "你好"}
140	 * 3. 要显示的emotion: {"emotion": "happy"}, 有这些取值:
141	 *           "neutral","happy","laughing","funny","sad","angry","crying","loving",
142	 *           "embarrassed","surprised","shocked","thinking","winking","cool","relaxed",
143	 *           "delicious","kissy","confident","sleepy","silly","confused"
144	 * 4. WIFI强度: {"wifi": 100}
145	 * 5. 电量: {"battery": 100}
146	 *
147	 * @param buffer 包含JSON格式数据的字符串缓冲区
148	 * @param size 缓冲区的大小
149	 * @param user_data 用户数据指针（未使用）
150	 * @return 0 表示成功，-1 表示解析错误
151	 */
152	static int process_ui_data(char *buffer, size_t size, void *user_data)
153	{
154	    cJSON *json;
155	    const char *state_str;
156	
157	    // 解析JSON数据
158	    json = cJSON_Parse(buffer);
159	    if (!json) {
160	        LV_LOG_USER("cJSON_Parse err: %s ", buffer);
161	        return -1;
162	    }
163	
164	    // 获取状态字段
165	    cJSON *state = cJSON_GetObjectItem(json, "state");
166	    if (state) {
167	        state_str = ConvertToLocalString((DeviceState)state->valueint);
168	        pthread_mutex_lock(&g_ui_update_lock);
169	        strlcpy(g_pending_ui_update.state, state_str,
170	                sizeof(g_pending_ui_update.state));
171	        g_pending_ui_update.state_valid = true;
172	        if (state->valueint == kDeviceStateSpeaking)
173	            {
174	                strlcpy(g_pending_ui_update.emotion, "laughing",
175	                        sizeof(g_pending_ui_update.emotion));
176	                g_pending_ui_update.emotion_valid = true;
177	            }
178	        if (state->valueint == kDeviceStateListening)
179	            {
180	                strlcpy(g_pending_ui_update.emotion, "happy",
181	                        sizeof(g_pending_ui_update.emotion));
182	                g_pending_ui_update.emotion_valid = true;
183	            }
184	        pthread_mutex_unlock(&g_ui_update_lock);
185	    }
186	
187	    // 获取文本字段
188	    cJSON *text = cJSON_GetObjectItem(json, "text");
189	    if (cJSON_IsString(text) && text->valuestring) {
190	        pthread_mutex_lock(&g_ui_update_lock);
191	        strlcpy(g_pending_ui_update.text, text->valuestring,
192	                sizeof(g_pending_ui_update.text));
193	        g_pending_ui_update.text_valid = true;
194	        pthread_mutex_unlock(&g_ui_update_lock);
195	    }
196	
197	    // 获取WIFI强度字段（未处理）
198	    cJSON *wifi = cJSON_GetObjectItem(json, "wifi");
199	    if (wifi) {
200	        pthread_mutex_lock(&g_ui_update_lock);
201	        g_pending_ui_update.wifi = wifi->valueint;
202	        g_pending_ui_update.wifi_valid = true;
203	        pthread_mutex_unlock(&g_ui_update_lock);
204	    }
205	
206	    // 获取电量字段（未处理）
207	    cJSON *battery = cJSON_GetObjectItem(json, "battery");
208	    if (battery) {
209	        // 处理电量
210	    }
211	
212	    // 释放JSON对象
213	    cJSON_Delete(json);
214	
215	    return 0;
216	}
